def tree_from_list(vals):
    if not vals:
        return None
    root = TreeNode(vals[0])
    queue = [root]
    i = 1
    while queue and i < len(vals):
        node = queue.pop(0)
        if i < len(vals) and vals[i] is not None:
            node.left = TreeNode(vals[i])
            queue.append(node.left)
        i += 1
        if i < len(vals) and vals[i] is not None:
            node.right = TreeNode(vals[i])
            queue.append(node.right)
        i += 1
    return root

def generate(rng, n):
    vals = list(range(n))
    rng.shuffle(vals)
    root = None
    for v in vals:
        if not root:
            root = TreeNode(v)
        else:
            curr = root
            while True:
                if v < curr.val:
                    if not curr.left:
                        curr.left = TreeNode(v)
                        break
                    curr = curr.left
                else:
                    if not curr.right:
                        curr.right = TreeNode(v)
                        break
                    curr = curr.right
    k = rng.randint(1, n)
    return [root, k]

def generate_worst(rng, n):
    vals = list(range(n))
    root = TreeNode(vals[0])
    curr = root
    for v in vals[1:]:
        curr.right = TreeNode(v)
        curr = curr.right
    return [root, n]

